<?php
/* Plugin Name: Nestora Store Tools
Description: Editable catalogue sections, private contact/subscriber records, local email logging, and demo-store tools.
Version: 1.0.0 */
if(!defined('ABSPATH'))exit;
// This store intentionally uses WooCommerce's classic checkout shortcode.
// The upstream development gateway's GitHub source has no compiled Blocks asset.
remove_action('woocommerce_blocks_loaded',['WC_Dummy_Payments','woocommerce_gateway_dummy_woocommerce_block_support']);
add_action('plugins_loaded',function(){remove_action('woocommerce_blocks_loaded',['WC_Dummy_Payments','woocommerce_gateway_dummy_woocommerce_block_support']);},0);
add_action('init',function(){foreach(['ns_message'=>'Store messages','ns_subscriber'=>'Nestora Club','ns_mail'=>'Store email log'] as $type=>$label)register_post_type($type,['label'=>$label,'public'=>false,'show_ui'=>true,'capability_type'=>'post','capabilities'=>['edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','read_private_posts'=>'manage_options','delete_posts'=>'manage_options','edit_post'=>'manage_options','read_post'=>'manage_options','delete_post'=>'manage_options'],'supports'=>['title','editor'],'menu_icon'=>'dashicons-store']);});
// The local assignment records emails instead of sending to unverified addresses.
add_filter('pre_wp_mail',function($return,$mail){if(!get_option('nestora_log_email',true))return $return;wp_insert_post(['post_type'=>'ns_mail','post_status'=>'private','post_title'=>sanitize_text_field($mail['subject']),'post_content'=>'To: '.esc_html(implode(', ',(array)$mail['to']))."\n\n".$mail['message']]);return true;},10,2);
add_filter('woocommerce_enable_setup_wizard','__return_false');add_filter('woocommerce_admin_disabled','__return_true');
add_shortcode('ns_categories',function(){ob_start();echo '<div class="ns-categories">';foreach(get_terms(['taxonomy'=>'product_cat','hide_empty'=>true,'orderby'=>'term_order']) as $term){$img=wp_get_attachment_image(get_term_meta($term->term_id,'thumbnail_id',true),'woocommerce_thumbnail');echo '<a class="ns-category" href="'.esc_url(get_term_link($term)).'">'.$img.'<span>'.esc_html($term->name).'<b>↗</b></span><small>'.(int)$term->count.' considered pieces</small></a>';}echo '</div>';return ob_get_clean();});
add_shortcode('ns_contact',function(){ob_start();$success=($_GET['message']??'')==='saved';if($success)echo '<div class="ns-notice" role="status">Thank you. Your message is saved in our local store dashboard.</div>';?><form class="ns-contact-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="ns_message"><?php wp_nonce_field('ns_message','ns_nonce');?><div class="ns-form-grid"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>Email address<input type="email" name="email" autocomplete="email" required maxlength="190"></label><label class="ns-full">Order number <small>(optional)</small><input name="order" maxlength="40"></label><label class="ns-full">How can we help?<textarea name="message" rows="6" required maxlength="5000"></textarea></label></div><label class="ns-consent"><input type="checkbox" name="consent" value="1" required> I agree to my details being used to answer this message.</label><div class="ns-honeypot" aria-hidden="true"><label>Leave empty<input name="website" tabindex="-1" autocomplete="off"></label></div><button type="submit">Send message ↗</button><p class="ns-small">Demo store: use sample details. Messages are stored locally; emails are logged.</p></form><?php return ob_get_clean();});
function ns_save_message(){if(!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ns_nonce']??'')),'ns_message'))wp_die('Please reload the form and try again.',403);$email=sanitize_email(wp_unslash($_POST['email']??''));$name=sanitize_text_field(wp_unslash($_POST['name']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$name||!is_email($email)||!$message||empty($_POST['consent'])||!empty($_POST['website']))wp_die('Complete the required fields.',400);$key='ns_message_'.hash('sha256',$_SERVER['REMOTE_ADDR']??'local');if(get_transient($key))wp_die('Please wait before sending another message.',429);wp_insert_post(['post_type'=>'ns_message','post_status'=>'private','post_title'=>$name.' — '.sanitize_text_field(wp_unslash($_POST['order']??'General enquiry')),'post_content'=>"Email: $email\n\n$message"]);set_transient($key,1,20);wp_safe_redirect(home_url('/contact/?message=saved'));exit;}
add_action('admin_post_ns_message','ns_save_message');add_action('admin_post_nopriv_ns_message','ns_save_message');
add_shortcode('ns_newsletter',function(){ob_start();if(($_GET['club']??'')==='joined')echo '<div class="ns-notice" role="status">Welcome to the club. Use WELCOME10 for 10% off your first order.</div>';?><form class="ns-newsletter" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="ns_join"><?php wp_nonce_field('ns_join','ns_nonce');?><label class="screen-reader-text" for="ns-club-email">Email address</label><input id="ns-club-email" name="email" type="email" placeholder="Your email address" required><button type="submit">Join the club ↗</button><label class="ns-consent"><input type="checkbox" name="consent" value="1" required> I agree to join the demo mailing list. <a href="<?php echo esc_url(home_url('/privacy/'));?>">Privacy notice</a></label></form><?php return ob_get_clean();});
function ns_join(){if(!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['ns_nonce']??'')),'ns_join'))wp_die('Reload the form.',403);$email=sanitize_email(wp_unslash($_POST['email']??''));if(!is_email($email)||empty($_POST['consent']))wp_die('A valid email and consent are required.',400);$existing=get_posts(['post_type'=>'ns_subscriber','post_status'=>'private','title'=>$email,'numberposts'=>1]);if(!$existing)wp_insert_post(['post_type'=>'ns_subscriber','post_status'=>'private','post_title'=>$email,'post_content'=>'Consented to the local Nestora Club demonstration.']);wp_safe_redirect(home_url('/?club=joined#club'));exit;}
add_action('admin_post_ns_join','ns_join');add_action('admin_post_nopriv_ns_join','ns_join');
add_action('woocommerce_before_checkout_form',function(){echo '<p class="ns-demo-payment" role="note">Coursework checkout: Cash on Delivery or WooCommerce’s official test gateway. No real card payment is collected.</p>';},5);
add_action('admin_menu',function(){add_management_page('Nestora handover','Nestora handover','manage_options','nestora-handover',function(){echo '<div class="wrap"><h1>Nestora handover</h1><p>Ecomus child theme. Pages use editable WordPress blocks. Products, prices, stock and images are editable in Products.</p><p>Payments: official WooCommerce Dummy Payments test gateway plus Cash on Delivery. Dummy Payments supports Success / Failure in WooCommerce → Settings → Payments. No external processor transaction is claimed.</p><p>Emails are recorded in Store email log. Set nestora_log_email to false only after configuring and testing SMTP.</p><p>Database: native MySQL. Exports and restoration instructions are included in the private handover ZIP.</p></div>';});});
